#!/usr/bin/env node

/*
    A typecheck that a changed analyzer cannot fool.

    MSBuild skips a compile whose `.cs` files have not changed, so a freshly built analyzer never
    runs and the gate prints what a pass prints -- `typecheck:tests` exited 0 on a tree the same
    command reported four WPROTO044 errors on once `obj/` was deleted (session 238). Deleting
    `obj/` is not sufficient either: a shared Roslyn compiler server served a stale file snapshot
    and reported diagnostics at pre-edit line numbers for edits already on disk (session 239).

    So this does both halves. `UseSharedCompilation` is passed through the environment, which
    MSBuild reads as a global property, so it reaches every project in the chain without editing
    twenty script lines.

    Reach for it when the change adds or widens a diagnostic -- the discriminator is whether an
    analyzer DLL is in the diff -- not on every run. It is several times slower than
    `npm run typecheck:unity`.
*/

const { spawnSync } = require("node:child_process");
const { existsSync, readdirSync, rmSync, statSync } = require("node:fs");
const path = require("node:path");

const repoRoot = path.resolve(__dirname, "..");
const generatorRoot = path.join(repoRoot, "Generator~");

if (!existsSync(generatorRoot)) {
  console.error(`[typecheck-clean] ${generatorRoot} does not exist.`);
  process.exit(2);
}

let removed = 0;
for (const entry of readdirSync(generatorRoot)) {
  const projectRoot = path.join(generatorRoot, entry);
  if (!statSync(projectRoot).isDirectory()) {
    continue;
  }

  for (const artifact of ["obj", "bin"]) {
    const target = path.join(projectRoot, artifact);
    if (!existsSync(target)) {
      continue;
    }

    rmSync(target, { recursive: true, force: true });
    removed++;
  }
}

console.log(
  `[typecheck-clean] Removed ${removed} build artifact ` +
    `${removed === 1 ? "directory" : "directories"}; shared compilation is off for this run.`
);

const requested = process.argv.slice(2);
const target = requested.length === 0 ? ["typecheck:unity"] : requested;
const npm = process.platform === "win32" ? "npm.cmd" : "npm";
const result = spawnSync(npm, ["run", ...target], {
  cwd: repoRoot,
  stdio: "inherit",
  env: { ...process.env, UseSharedCompilation: "false" }
});

if (result.error) {
  console.error(`[typecheck-clean] ${result.error.message}`);
  process.exit(1);
}

process.exit(result.status === null ? 1 : result.status);

lint-csharp-format.ps1:
# PositionalBinding = $false so a stray value cannot be captured by a named parameter before
# the ValueFromRemainingArguments sibling sees it. With it on -- the default -- the sibling
# only works when every other parameter is a switch, which is an accident of this param list
# rather than a property of it (#556).
[CmdletBinding(PositionalBinding = $false)]
Param(
  [switch]$VerboseOutput,
  [switch]$Fix,
  # Report a missing tool manifest or a missing dotnet as a skip rather than a failure. Only the
  # changed-file pass uses this, so it can run inside a scratch repository that has neither; the
  # whole-repository check in validate:local never sets it, which is what keeps the gate real.
  [switch]$SkipWhenUnavailable,
  [string[]]$Paths,
  # `pwsh -File <script> -Paths a b c` binds ONLY `a` to -Paths and silently drops the rest, so a
  # multi-file invocation scans one file and reports success. This catches the remainder; see
  # .llm/skills/bash-pwsh-invocation.md.
  [Parameter(ValueFromRemainingArguments = $true)]
  [string[]]$AdditionalPaths
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

# The remaining-args catch above is only half of it: the two have to be merged before anything
# reads $Paths, or the extra files are collected and ignored.
if ($AdditionalPaths) {
  $Paths = @($Paths) + @($AdditionalPaths)
}

$scriptRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$repoRoot = Split-Path -Parent $scriptRoot

function Write-Info($msg) {
  if ($VerboseOutput) {
    Write-Host "[lint-csharp-format] $msg" -ForegroundColor Cyan
  }
}

function Write-Failure($msg) {
  Write-Host "[lint-csharp-format] $msg" -ForegroundColor Red
}

function Write-Remedy($msg) {
  Write-Host "  $msg" -ForegroundColor Yellow
}

function Exit-Unavailable([string]$Reason, [string[]]$Remedies) {
  if ($SkipWhenUnavailable) {
    # Announced, never silent. A gate that quietly does nothing is the defect this script exists
    # to close, so the skip is always printed even outside verbose mode.
    Write-Host "[lint-csharp-format] Skipped: $Reason" -ForegroundColor Yellow
    exit 0
  }

  Write-Failure $Reason
  foreach ($remedy in $Remedies) {
    Write-Remedy $remedy
  }

  exit 1
}

$manifestPath = Join-Path -Path $repoRoot -ChildPath '.config/dotnet-tools.json'
if (-not (Test-Path -LiteralPath $manifestPath)) {
  Exit-Unavailable 'no .NET tool manifest at .config/dotnet-tools.json.' @(
    'CSharpier is pinned there; restore the file before formatting C#.'
  )
}

if (-not (Get-Command dotnet -ErrorAction SilentlyContinue)) {
  Exit-Unavailable 'dotnet was not found on PATH, so C# formatting cannot be verified.' @(
    'Install the .NET SDK, then run: dotnet tool restore',
    'CI runs "dotnet tool run csharpier check ." and will reject unformatted C# regardless.'
  )
}

# CSharpier only reaches the repository's pinned version through the manifest, and the manifest is
# only honored from the repository root -- a caller-relative invocation silently resolves a
# different (or no) tool.
Push-Location $repoRoot
try {
  Write-Info 'Restoring .NET tools.'
  $restoreOutput = & dotnet tool restore 2>&1
  if ($LASTEXITCODE -ne 0) {
    Write-Failure "dotnet tool restore failed with exit code $LASTEXITCODE."
    foreach ($line in @($restoreOutput)) {
      Write-Host "  $line" -ForegroundColor DarkGray
    }
    Write-Remedy 'Run "dotnet tool restore" from the repository root and resolve the error above.'
    exit 1
  }

  $targets = @()
  if ($null -ne $Paths) {
    $targets = @($Paths | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
  }

  $scopeLabel = 'the repository'
  if ($targets.Count -gt 0) {
    # A path list that resolves to nothing must not become a whole-repository run: the caller asked
    # about specific files, and silently widening the scope hides which files were actually checked.
    $existing = @($targets | Where-Object {
        $candidate = $_
        if ([System.IO.Path]::IsPathRooted($candidate)) {
          Test-Path -LiteralPath $candidate
        }
        else {
          Test-Path -LiteralPath (Join-Path -Path $repoRoot -ChildPath $candidate)
        }
      })

    if ($existing.Count -eq 0) {
      Write-Info 'No existing C# targets to check.'
      exit 0
    }

    $targets = $existing
    $scopeLabel = "$($targets.Count) changed file(s)"
  }
  else {
    $targets = @('.')
  }

  $verb = if ($Fix) { 'format' } else { 'check' }
  Write-Info "Running csharpier $verb over $scopeLabel."

  $arguments = @('tool', 'run', 'csharpier', $verb) + $targets
  & dotnet @arguments
  $exitCode = $LASTEXITCODE

  if ($exitCode -ne 0) {
    if ($Fix) {
      Write-Failure "csharpier format failed with exit code $exitCode."
    }
    else {
      Write-Failure "C# formatting does not match CSharpier ($scopeLabel)."
      Write-Remedy 'Fix with: dotnet tool run csharpier format .'
      Write-Remedy 'Or scope it: npm run agent:preflight:fix'
    }

    exit $exitCode
  }
}
finally {
  Pop-Location
}

Write-Info 'C# formatting matches CSharpier.'
exit 0
